import React from 'react';
import { useNavigate } from 'react-router-dom';

export default function Dashboard() {
  const navigate = useNavigate();
  return (
    <div style={{
      display: 'flex', alignItems: 'center', justifyContent: 'center',
      height: '100vh', background: '#f9fafb'
    }}>
      <div style={{
        background: 'white', borderRadius: 20, boxShadow: '0 8px 32px rgba(0,0,0,0.1)',
        padding: '48px 40px', textAlign: 'center', maxWidth: 400
      }}>
        <div style={{ fontSize: 56, marginBottom: 16 }}>🏦</div>
        <h1 style={{ fontSize: '1.5rem', fontWeight: 700, color: '#1f2937', marginBottom: 8 }}>
          Welcome, EMP001!
        </h1>
        <p style={{ color: '#6b7280', marginBottom: 24 }}>
          You are successfully logged in to SecureBank.
        </p>
        <button
          onClick={() => navigate('/')}
          style={{
            background: '#1d4ed8', color: 'white', border: 'none',
            padding: '12px 28px', borderRadius: 12, fontWeight: 600,
            fontSize: '1rem', cursor: 'pointer'
          }}
        >
          Logout
        </button>
      </div>
    </div>
  );
}
